"""specs_s200023.py - Sonnet-w2 family B (generated by mkfamB.py). Hooks: 0x45c4f0 (cdecl size, b), 0x45c4b0 (cdecl size) and the member's init callee (thiscall, 3 stack args,
callee pops 0xc) record the SEH chain (seh_record); fake outer SEH records 0-2; fs:[0] compared. b is zero in about half of the cases; the allocators return 0 sometimes."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(init):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x400), rnd(c, 0x400), rnd(c, 0x400)])
        hook_rec(c, 0x45c4f0, 2, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, 0x45c4b0, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, init, 3, ret=r.getrandbits(32), pop=12, this=True, side=seh_record(c, 2))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), r.choice([0, 0, 1, r.getrandbits(32)])]
    return gen


S(0x45b6a0, 'GUESS famB 0x45b6a0', 'fastcall', None, ret='eax', gen=_mk(0x45b240), note='batch200023')
